// CATALOG.md: what the test world holds and what each piece is there for. Generated by
// `npm run world:update` from the parts and their PURPOSE tables; world.test.mjs fails while
// it is stale.

import prettier from "prettier";
import { buildExampleWorld, PARTS } from "./index.mjs";
import { PURPOSE as BASE_PURPOSE } from "./parts/base.mjs";
import { PURPOSE as EDGE_PURPOSE } from "./parts/edge.mjs";

export const CATALOG_FILE = "tests/world/CATALOG.md";

/** The purpose of every entry, per part. */
export const PURPOSES = { base: BASE_PURPOSE, edge: EDGE_PURPOSE };

const cell = (text) => String(text ?? "").replaceAll("|", "\\|");

/** Which part each id comes from: the base world first, every later part after it. */
export function partOfIds() {
  const owner = new Map();
  let built = [];
  for (const part of PARTS) {
    const include = PARTS.slice(0, PARTS.indexOf(part) + 1);
    const world = buildExampleWorld("de", { include });
    const ids = everyId(world);
    for (const id of ids) if (!owner.has(id) && !built.includes(id)) owner.set(id, part);
    built = ids;
  }
  return owner;
}

/** Every id the world gives out that a catalog row can stand for. */
function everyId({ manuscript, figures, storyboards }) {
  return [
    ...figures.nodes.map((node) => node.id),
    ...manuscript.chapters.map((chapter) => chapter.id),
    ...manuscript.trash.map((entry) => entry.chapter.id),
    ...storyboards.boards.map((board) => board.id),
    ...storyboards.nodes.map((card) => card.id),
  ];
}

export async function renderCatalog() {
  const world = buildExampleWorld("de", { include: PARTS });
  const owner = partOfIds();
  const purpose = (id) => PURPOSES[owner.get(id)]?.[id] ?? "";
  const table = (head, rows) => [
    `| ${head.join(" | ")} |`,
    `| ${head.map(() => "---").join(" | ")} |`,
    ...rows.map((row) => `| ${row.map(cell).join(" | ")} |`),
  ];
  const { manuscript, figures, storyboards } = world;
  const lines = [
    "# Test world catalog",
    "",
    "Generated from `tests/world/` by `npm run world:update`. Do not edit; change the parts and",
    "their `PURPOSE` tables instead. Names are the German texts. The base part is photographed",
    "for the README and ships as the example world; the edge part (ids `x-...`) never does.",
    "",
    "## Elements",
    "",
    ...table(
      ["Id", "Part", "Kind", "Name", "Purpose"],
      figures.nodes.map((node) => [
        `\`${node.id}\``,
        owner.get(node.id),
        node.type,
        node.name,
        purpose(node.id),
      ]),
    ),
    "",
    "## Chapters",
    "",
    ...table(
      ["Id", "Part", "Where", "Title", "Purpose"],
      [
        ...manuscript.chapters.map((chapter) => {
          const item = manuscript.structure.items.find((entry) => entry.chapterId === chapter.id);
          return [
            `\`${chapter.id}\``,
            owner.get(chapter.id),
            item?.parentFolderId ?? "",
            chapter.title,
            purpose(chapter.id),
          ];
        }),
        ...manuscript.trash.map((entry) => [
          `\`${entry.chapter.id}\``,
          owner.get(entry.chapter.id),
          "bin",
          entry.chapter.title,
          purpose(entry.chapter.id),
        ]),
      ],
    ),
    "",
    "## Moments",
    "",
    ...table(
      ["Id", "Time", "Title"],
      figures.timeline.map((moment) => [`\`${moment.id}\``, moment.time, moment.title]),
    ),
    "",
    "## Storyboards",
    "",
    ...table(
      ["Id", "Part", "Board", "Kind", "Label or target", "Purpose"],
      [
        ...storyboards.boards.map((board) => [
          `\`${board.id}\``,
          owner.get(board.id),
          "",
          "board",
          board.title,
          purpose(board.id),
        ]),
        ...storyboards.nodes.map((card) => [
          `\`${card.id}\``,
          owner.get(card.id),
          card.boardId,
          card.kind,
          card.target ? `${card.target.kind}:${card.target.id}` : card.label,
          purpose(card.id),
        ]),
      ],
    ),
    "",
  ];
  const options = (await prettier.resolveConfig(CATALOG_FILE)) ?? {};
  const formatted = await prettier.format(lines.join("\n"), { ...options, parser: "markdown" });
  return Buffer.from(formatted, "utf8");
}
